package com.marketrealms;

import net.kyori.adventure.text.Component;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.*;
import org.bukkit.configuration.file.YamlConfiguration;
import java.util.*;
import com.marketrealms.Domain.Currency;
import static com.marketrealms.Domain.*;

final class Trades implements Listener {
    record Request(UUID sender,long expires){ }
    static final class Offer {final Map<Integer,ItemStack> slots=new LinkedHashMap<>();long emeralds,money;boolean confirmed;}
    static final class Session {String id;UUID first,second;final Offer a=new Offer(),b=new Offer();boolean closing;Offer offer(UUID p){return p.equals(first)?a:b;}UUID other(UUID p){return p.equals(first)?second:first;}}
    static final class View implements InventoryHolder {final UUID owner;final Session session;Inventory inventory;View(UUID p,Session s){owner=p;session=s;}public Inventory getInventory(){return inventory;}}
    private final MarketRealmsPlugin plugin;private final Map<UUID,Session> sessions=new HashMap<>();private final Map<UUID,Request> requests=new HashMap<>();private final Map<UUID,Long> last=new HashMap<>();
    Trades(MarketRealmsPlugin plugin){this.plugin=plugin;Bukkit.getScheduler().runTaskTimer(plugin,()->{long now=System.currentTimeMillis();requests.values().removeIf(r->r.expires()<now);for(Session s:new HashSet<>(sessions.values())){Player a=Bukkit.getPlayer(s.first),b=Bukkit.getPlayer(s.second);if(a==null||b==null||a.getWorld()!=b.getWorld()||a.getLocation().distanceSquared(b.getLocation())>Math.pow(plugin.config.file("trade").getDouble("maximum-distance"),2))cancelId(s,"Participants moved apart");}},20,20);}
    void command(Player p,String[] args){if(!plugin.config.file("trade").getBoolean("enabled"))throw new IllegalArgumentException("Trading disabled");plugin.journal.require(p);if(args.length==0)throw new IllegalArgumentException("/trade <player> | accept | decline | cancel");switch(args[0].toLowerCase(Locale.ROOT)){case "accept"->accept(p);case "decline"->{requests.remove(p.getUniqueId());plugin.info(p,"Trade request declined");}case "cancel"->cancel(p,"Cancelled");default->{Player other=Bukkit.getPlayerExact(args[0]);if(other==null||other.equals(p))throw new IllegalArgumentException("Choose another online player");plugin.journal.require(other);if(!other.hasPermission("marketrealms.trade"))throw new IllegalArgumentException("Recipient cannot trade");if(sessions.containsKey(p.getUniqueId())||sessions.containsKey(other.getUniqueId()))throw new IllegalArgumentException("A participant already has a trade");if(p.getWorld()!=other.getWorld()||p.getLocation().distanceSquared(other.getLocation())>Math.pow(plugin.config.file("trade").getDouble("maximum-distance"),2))throw new IllegalArgumentException("Stand near the other player in the same world");long now=System.currentTimeMillis();if(now-last.getOrDefault(p.getUniqueId(),0L)<plugin.config.file("trade").getLong("request-cooldown-seconds")*1000)throw new IllegalArgumentException("Trade request cooldown");if(requests.containsKey(other.getUniqueId()))throw new IllegalArgumentException("Recipient already has a pending request");last.put(p.getUniqueId(),now);requests.put(other.getUniqueId(),new Request(p.getUniqueId(),now+plugin.config.file("trade").getLong("request-timeout-seconds")*1000));plugin.info(other,p.getName()+" requests a trade. /trade accept or /trade decline");plugin.info(p,"Trade request sent");}}}
    private void accept(Player p){Request request=requests.remove(p.getUniqueId());if(request==null||request.expires()<System.currentTimeMillis())throw new IllegalArgumentException("No active request");Player other=Bukkit.getPlayer(request.sender());if(other==null)throw new IllegalArgumentException("Requester went offline");plugin.journal.require(other);if(sessions.containsKey(p.getUniqueId())||sessions.containsKey(other.getUniqueId()))throw new IllegalArgumentException("Already trading");if(p.getWorld()!=other.getWorld()||p.getLocation().distanceSquared(other.getLocation())>Math.pow(plugin.config.file("trade").getDouble("maximum-distance"),2))throw new IllegalArgumentException("Requester moved away");Session s=new Session();s.id=UUID.randomUUID().toString();s.first=other.getUniqueId();s.second=p.getUniqueId();sessions.put(s.first,s);sessions.put(s.second,s);plugin.db.update("INSERT INTO trades VALUES(?,?,?,'OPEN','',?)",s.id,s.first.toString(),s.second.toString(),System.currentTimeMillis());open(p,s);open(other,s);save(s);}
    private void open(Player p,Session s){View v=new View(p.getUniqueId(),s);v.inventory=Bukkit.createInventory(v,54,Component.text("Trade: your offer | their offer"));draw(v);p.openInventory(v.inventory);}
    private void draw(View v){v.inventory.clear();Offer mine=v.session.offer(v.owner),theirs=v.session.offer(v.session.other(v.owner));int i=0;for(ItemStack stack:mine.slots.values())v.inventory.setItem(i++,stack.clone());i=18;for(ItemStack stack:theirs.slots.values())v.inventory.setItem(i++,stack.clone());v.inventory.setItem(45,Menus.icon(Material.EMERALD,"Your emeralds: "+mine.emeralds,"Left: +1; right: -1; shift: 64","Their emeralds: "+theirs.emeralds));v.inventory.setItem(46,Menus.icon(Material.GOLD_INGOT,"Your money: "+moneyText(mine.money),"Left/right: adjust by configured step","Their money: "+moneyText(theirs.money)));v.inventory.setItem(49,Menus.icon(mine.confirmed?Material.LIME_WOOL:Material.YELLOW_WOOL,mine.confirmed?"Confirmed":"Confirm exact offer","Their confirmation: "+theirs.confirmed,"Changes reset both confirmations"));v.inventory.setItem(53,Menus.icon(Material.BARRIER,"Cancel trade","Items remain in original inventories until completion"));}
    private void changed(Session s){s.a.confirmed=false;s.b.confirmed=false;save(s);refresh(s);}
    private void save(Session s){YamlConfiguration y=new YamlConfiguration();for(var side:List.of(Map.entry("first",s.a),Map.entry("second",s.b))){y.set(side.getKey()+".items",Items.encode(side.getValue().slots.values().toArray(ItemStack[]::new)));y.set(side.getKey()+".emeralds",side.getValue().emeralds);y.set(side.getKey()+".money",side.getValue().money);}plugin.db.update("UPDATE trades SET payload=? WHERE id=? AND state='OPEN'",y.saveToString(),s.id);}
    private void refresh(Session s){for(UUID id:List.of(s.first,s.second)){Player p=Bukkit.getPlayer(id);if(p!=null&&p.getOpenInventory().getTopInventory().getHolder() instanceof View v&&v.session==s)draw(v);}}
    @EventHandler(priority=EventPriority.HIGHEST)public void click(InventoryClickEvent e){if(!(e.getInventory().getHolder() instanceof View view))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(view.owner)||sessions.get(view.owner)!=view.session)return;Session s=view.session;Offer mine=s.offer(view.owner);try{plugin.journal.require(p);if(e.getClickedInventory()==p.getInventory()){int slot=e.getSlot();if(slot<0||slot>=36)return;ItemStack item=p.getInventory().getItem(slot);if(item==null||item.getType().isAir())return;if(mine.slots.containsKey(slot))mine.slots.remove(slot);else{if(mine.slots.size()>=plugin.config.file("trade").getInt("maximum-offer-slots"))throw new IllegalArgumentException("Offer is full");mine.slots.put(slot,item.clone());}changed(s);return;}int raw=e.getRawSlot();if(raw<18){List<Integer> slots=new ArrayList<>(mine.slots.keySet());if(raw<slots.size()){mine.slots.remove(slots.get(raw));changed(s);}return;}if(raw==53){cancelId(s,"Cancelled");return;}if(raw==45){long step=e.isShiftClick()?64:plugin.config.file("trade").getLong("emerald-step");mine.emeralds=Math.max(0,Math.min(2304,mine.emeralds+(e.isRightClick()?-step:step)));changed(s);}if(raw==46){if(!plugin.config.file("trade").getBoolean("allow-money"))throw new IllegalArgumentException("Money trading disabled");plugin.money.require();long step=cents(plugin.config.file("trade").getString("money-step"));mine.money=Math.max(0,Math.min(1_000_000_000L,mine.money+(e.isRightClick()?-step:step)));changed(s);}if(raw==49){validateOffer(p,mine);mine.confirmed=true;refresh(s);if(s.a.confirmed&&s.b.confirmed)complete(s);}}catch(RuntimeException ex){plugin.error(p,ex.getMessage());if(sessions.containsKey(view.owner))changed(s);}}
    private ItemStack[] validateOffer(Player p,Offer offer){var before=p.getInventory().getStorageContents();var result=Items.copy(before);for(var entry:offer.slots.entrySet()){int slot=entry.getKey();if(slot<0||slot>=36||!Objects.equals(before[slot],entry.getValue()))throw new IllegalArgumentException("Offered item changed; remove it and select again");result[slot]=null;}if(offer.emeralds>0)result=Items.remove(result,Items.emerald(),(int)offer.emeralds);if(offer.money>0&&plugin.money.balance(p.getUniqueId())+1e-7<offer.money/100.0)throw new IllegalArgumentException("Insufficient money");return result;}
    private void complete(Session s){Player a=Bukkit.getPlayer(s.first),b=Bukkit.getPlayer(s.second);if(a==null||b==null||a.isDead()||b.isDead()||a.getWorld()!=b.getWorld()||a.getLocation().distanceSquared(b.getLocation())>Math.pow(plugin.config.file("trade").getDouble("maximum-distance"),2))throw new IllegalArgumentException("Trade conditions changed");var aBefore=a.getInventory().getStorageContents();var bBefore=b.getInventory().getStorageContents();var aAfter=Items.addAll(validateOffer(a,s.a),s.b.slots.values().toArray(ItemStack[]::new));var bAfter=Items.addAll(validateOffer(b,s.b),s.a.slots.values().toArray(ItemStack[]::new));if(s.b.emeralds>0)aAfter=Items.add(aAfter,Items.emerald(),(int)s.b.emeralds);if(s.a.emeralds>0)bAfter=Items.add(bAfter,Items.emerald(),(int)s.a.emeralds);List<Journal.Charge> charges=new ArrayList<>();if(s.a.money>0)charges.add(new Journal.Charge(s.first,s.a.money));if(s.b.money>0)charges.add(new Journal.Charge(s.second,s.b.money));plugin.db.update("UPDATE trades SET state='FINALIZING' WHERE id=? AND state='OPEN'",s.id);
        try{plugin.journal.execute("TRADE",List.of(new Journal.Change(a,aBefore,aAfter),new Journal.Change(b,bBefore,bAfter)),charges,Map.of("trade",s.id),op->{if(s.a.money>0)plugin.journal.credit(s.second,Currency.MONEY,s.a.money);if(s.b.money>0)plugin.journal.credit(s.first,Currency.MONEY,s.b.money);plugin.db.update("UPDATE trades SET state='COMMITTED' WHERE id=?",s.id);return null;});finish(s);plugin.success(a,"Trade completed. Any Vault money received is claimable with /market sales.");plugin.success(b,"Trade completed. Any Vault money received is claimable with /market sales.");}catch(RuntimeException e){plugin.db.update("UPDATE trades SET state=? WHERE id=?",plugin.journal.locked(s.first)||plugin.journal.locked(s.second)?"REVIEW":"CANCELLED",s.id);finish(s);throw e;}}
    @EventHandler(priority=EventPriority.HIGHEST)public void drag(InventoryDragEvent e){if(e.getInventory().getHolder() instanceof View)e.setCancelled(true);}
    @EventHandler public void close(InventoryCloseEvent e){if(e.getInventory().getHolder() instanceof View v&&!v.session.closing)cancelId(v.session,"Window closed");}
    void cancel(Player p,String reason){Session s=sessions.get(p.getUniqueId());if(s!=null)cancelId(s,reason);requests.remove(p.getUniqueId());requests.values().removeIf(r->r.sender().equals(p.getUniqueId()));}
    private void cancelId(Session s,String reason){if(s.closing)return;plugin.db.update("UPDATE trades SET state='CANCELLED' WHERE id=? AND state='OPEN'",s.id);finish(s);for(UUID id:List.of(s.first,s.second)){Player p=Bukkit.getPlayer(id);if(p!=null)plugin.message(p,"trade-cancel",Map.of());}}
    private void finish(Session s){s.closing=true;sessions.remove(s.first);sessions.remove(s.second);for(UUID id:List.of(s.first,s.second)){Player p=Bukkit.getPlayer(id);if(p!=null&&p.getOpenInventory().getTopInventory().getHolder() instanceof View)p.closeInventory();}}
    @EventHandler public void quit(PlayerQuitEvent e){cancel(e.getPlayer(),"Disconnected");}@EventHandler public void death(PlayerDeathEvent e){cancel(e.getEntity(),"Died");}@EventHandler public void world(PlayerChangedWorldEvent e){cancel(e.getPlayer(),"World changed");}
    void closeAll(){for(Session s:new HashSet<>(sessions.values()))cancelId(s,"Plugin stopped/reloaded");requests.clear();}
    boolean active(Player p){return sessions.containsKey(p.getUniqueId());}
}
